#!/usr/bin/env python3
"""Deterministic verifier for case 05; uses only the standard library."""

from __future__ import annotations

import json
import math
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
OUTPUT = ROOT / "result.json"


class VerificationError(Exception):
    pass


def fail(message: str) -> None:
    raise VerificationError(message)


def finite_number(value, label: str) -> float:
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        fail(f"{label} 必须是数值")
    value = float(value)
    if not math.isfinite(value):
        fail(f"{label} 必须是有限数")
    return value


def numeric_vector(value, length: int, label: str) -> list[float]:
    if not isinstance(value, list) or len(value) != length:
        fail(f"{label} 必须是长度为 {length} 的数组")
    return [finite_number(item, f"{label}[{i}]") for i, item in enumerate(value)]


def root_residuals(v: list[float]) -> list[float]:
    x, y, z = v
    return [
        math.sin(x) + y * y + z - 2.6773560908995230,
        math.exp(x) + x * y - z - 0.5955409284924678,
        x * x + 2 * y * y + 0.5 * z * z - 3.3412500000000005,
    ]


def ode_rhs(t: float, state: tuple[float, float]) -> tuple[float, float]:
    theta, omega = state
    return omega, -0.18 * omega - 2.4 * math.sin(theta) + 0.35 * math.cos(1.3 * t)


def rk4_step(t: float, state: tuple[float, float], h: float) -> tuple[float, float]:
    k1 = ode_rhs(t, state)
    s2 = (state[0] + 0.5 * h * k1[0], state[1] + 0.5 * h * k1[1])
    k2 = ode_rhs(t + 0.5 * h, s2)
    s3 = (state[0] + 0.5 * h * k2[0], state[1] + 0.5 * h * k2[1])
    k3 = ode_rhs(t + 0.5 * h, s3)
    s4 = (state[0] + h * k3[0], state[1] + h * k3[1])
    k4 = ode_rhs(t + h, s4)
    return (
        state[0] + h * (k1[0] + 2 * k2[0] + 2 * k3[0] + k4[0]) / 6,
        state[1] + h * (k1[1] + 2 * k2[1] + 2 * k3[1] + k4[1]) / 6,
    )


def reference_ode() -> list[tuple[float, float, float]]:
    # h=0.0005 makes the independent RK4 reference much tighter than the task tolerance.
    t = 0.0
    state = (1.2, -0.4)
    h = 0.0005
    steps_per_sample = 200
    out = [(t, *state)]
    for sample_index in range(1, 161):
        for _ in range(steps_per_sample):
            state = rk4_step(t, state, h)
            t += h
        out.append((sample_index / 10, *state))
    return out


def objective(v: list[float]) -> float:
    x, y, z = v
    return (
        (x - 1.5) ** 2
        + 2 * (y + 0.8) ** 2
        + 0.5 * (z - 2.2) ** 2
        + 0.15 * math.sin(3 * x + z)
        + 0.03 * (x * y * z) ** 2
    )


# Obtained from a high-precision solve and cross-checked from a dense set of feasible starts.
OPTIMUM_OBJECTIVE = 0.1202688279181223


def check_root(section) -> None:
    if not isinstance(section, dict):
        fail("nonlinear_root 必须是对象")
    solution = numeric_vector(section.get("solution"), 3, "nonlinear_root.solution")
    stated = numeric_vector(section.get("residuals"), 3, "nonlinear_root.residuals")
    bounds = [(0.65, 0.95), (-1.35, -0.95), (0.55, 0.95)]
    for i, (value, (lo, hi)) in enumerate(zip(solution, bounds)):
        if not lo <= value <= hi:
            fail(f"非线性解第 {i + 1} 个分量越界")
    actual = root_residuals(solution)
    for i, (a, s) in enumerate(zip(actual, stated)):
        if abs(a) > 2e-8:
            fail(f"非线性方程 {i + 1} 残差过大: {a:.3g}")
        if abs(a - s) > 5e-9:
            fail(f"nonlinear_root.residuals[{i}] 与实际解不一致")


def check_ode(section) -> None:
    if not isinstance(section, dict) or not isinstance(section.get("samples"), list):
        fail("ode.samples 必须是数组")
    samples = section["samples"]
    if len(samples) != 161:
        fail(f"ode.samples 应有 161 项，实际为 {len(samples)}")
    reference = reference_ode()
    worst = 0.0
    for i, (item, ref) in enumerate(zip(samples, reference)):
        if not isinstance(item, dict):
            fail(f"ode.samples[{i}] 必须是对象")
        t = finite_number(item.get("t"), f"ode.samples[{i}].t")
        theta = finite_number(item.get("theta"), f"ode.samples[{i}].theta")
        omega = finite_number(item.get("omega"), f"ode.samples[{i}].omega")
        if abs(t - ref[0]) > 5e-10:
            fail(f"ode.samples[{i}] 的采样时刻错误")
        error = max(abs(theta - ref[1]), abs(omega - ref[2]))
        worst = max(worst, error)
        if error > 2e-5:
            fail(f"ode.samples[{i}] 状态误差过大: {error:.3g}")
    print(f"ODE 最大状态误差: {worst:.3g}")


def check_optimization(section) -> None:
    if not isinstance(section, dict):
        fail("optimization 必须是对象")
    v = numeric_vector(section.get("solution"), 3, "optimization.solution")
    stated_objective = finite_number(section.get("objective"), "optimization.objective")
    constraints = section.get("constraints")
    if not isinstance(constraints, dict):
        fail("optimization.constraints 必须是对象")
    x, y, z = v
    for i, (value, lo, hi) in enumerate(zip(v, (-1.0, -1.8, 0.2), (2.2, 1.2, 3.0))):
        if value < lo - 2e-7 or value > hi + 2e-7:
            fail(f"优化变量 {i + 1} 越界")
    equality = x + y + z - 2.6
    slacks = [3.0 - x * x - y * y, z - 0.4, x - y - 0.5, 2.6 - x - 0.4 * z]
    stated_equalities = numeric_vector(constraints.get("equality_residuals"), 1, "optimization.constraints.equality_residuals")
    stated_slacks = numeric_vector(constraints.get("inequality_slacks"), 4, "optimization.constraints.inequality_slacks")
    if abs(equality) > 2e-7:
        fail(f"优化等式约束误差过大: {equality:.3g}")
    if min(slacks) < -2e-7:
        fail(f"优化不等式约束越界: {-min(slacks):.3g}")
    if abs(stated_equalities[0] - equality) > 5e-9:
        fail("optimization.constraints.equality_residuals 与 solution 不一致")
    for i, (stated, actual_slack) in enumerate(zip(stated_slacks, slacks)):
        if abs(stated - actual_slack) > 5e-9:
            fail(f"optimization.constraints.inequality_slacks[{i}] 与 solution 不一致")
    actual = objective(v)
    if abs(actual - stated_objective) > 2e-7:
        fail("optimization.objective 与 solution 不一致")
    if abs(actual - OPTIMUM_OBJECTIVE) > 2e-6:
        fail(f"目标值未达到最优邻域: {actual:.12g}")


def main() -> int:
    if not OUTPUT.is_file():
        print("FAIL: 缺少 result.json", file=sys.stderr)
        return 1
    try:
        with OUTPUT.open("r", encoding="utf-8") as handle:
            data = json.load(handle)
        if not isinstance(data, dict):
            fail("result.json 顶层必须是对象")
        check_root(data.get("nonlinear_root"))
        check_ode(data.get("ode"))
        check_optimization(data.get("optimization"))
    except (OSError, json.JSONDecodeError, VerificationError) as exc:
        print(f"FAIL: {exc}", file=sys.stderr)
        return 1
    print("PASS: 三个数值子任务均满足容差")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

